        [['question' => 'What does every secondary index leaf node in MySQL InnoDB store to locate the full row?', 'answer' => 'The Primary Key value of the row (requiring a bookmark lookup in the Clustered PK B+Tree unless covered)', 'options' => ['The Primary Key value of the row (requiring a bookmark lookup in the Clustered PK B+Tree unless covered)', 'A physical byte offset into a flat CSV file', 'A copy of every column in the table', 'An MD5 hash of the table name']], ['question' => 'Why was the legacy MySQL Query Cache completely removed in MySQL 8.0?', 'answer' => 'A single global mutex invalidated the entire table\'s cached queries on any write, hurting multi-core scalability', 'options' => ['A single global mutex invalidated the entire table\'s cached queries on any write, hurting multi-core scalability', 'RAM became slower than HDDs', 'SQL standards banned caching', 'InnoDB stopped supporting SELECT']], ['question' => 'What percentage of RAM should innodb_buffer_pool_size typically receive on a dedicated MySQL production server?', 'answer' => '70%–80% of total RAM', 'options' => ['70%–80% of total RAM', '2% of RAM', '100% of RAM (leaving 0 for OS)', 'Fixed at 128MB always']]],
