        [['question' => 'What critical limitation affects MySQL\'s 4-byte TIMESTAMP column type on January 19, 2038?', 'answer' => '32-bit signed epoch overflow (the Year 2038 problem); use DATETIME storing UTC for dates beyond 2038', 'options' => ['32-bit signed epoch overflow (the Year 2038 problem); use DATETIME storing UTC for dates beyond 2038', 'It resets to 1900 every leap year', 'It loses hours and minutes', 'It switches from UTC to IST']], ['question' => 'Why did legacy MySQL "utf8" fail when users submitted Emoji characters?', 'answer' => 'Legacy utf8 (utf8mb3) capped characters at 3 bytes, whereas Emojis require 4-byte UTF-8 (utf8mb4)', 'options' => ['Legacy utf8 (utf8mb3) capped characters at 3 bytes, whereas Emojis require 4-byte UTF-8 (utf8mb4)', 'MySQL blocked non-ASCII text', 'InnoDB stripped emojis', 'VARCHAR max length was 10']], ['question' => 'Does INT(3) restrict a MySQL column to storing numbers up to 999?', 'answer' => 'No—INT is always a 4-byte integer up to ~2.14 billion; display widths were only for ZEROFILL', 'options' => ['No—INT is always a 4-byte integer up to ~2.14 billion; display widths were only for ZEROFILL', 'Yes, 1000 throws Out of Range', 'It truncates digits to 3 chars', 'It converts to CHAR(3)']]],
        'Run the `DATEDIFF` query in the playground to see the exact countdown to the 32-bit `TIMESTAMP` limit!'
