    my_ch('1. InnoDB Architecture, Collations & Data Types', 'Table Design, Foreign Keys, Generated Columns & Upserts (ON DUPLICATE KEY UPDATE)', 'mysql create table foreign key, generated columns virtual stored, on duplicate key update values alias',
        'Design normalized InnoDB schemas with indexed **Foreign Keys**, **Virtual/Stored Generated Columns**, and MySQL 8.0.20+ **`INSERT ... AS new ON DUPLICATE KEY UPDATE`** row aliases.',
        ['**InnoDB Automatically Indexes Foreign Keys**: Every `FOREIGN KEY (user_id)` requires an index where `user_id` is the leftmost column so parent `DELETE`/`UPDATE` checks don\'t trigger full child table scans!', '**Virtual vs Stored Generated Columns**: `full_name VARCHAR(200) GENERATED ALWAYS AS (CONCAT(first_name, \' \', last_name)) VIRTUAL` occupies **0 bytes on disk** yet **CAN be indexed** by InnoDB B-Trees!', '**MySQL 8.0.20+ Upsert Syntax**: Legacy `VALUES(col)` inside `ON DUPLICATE KEY UPDATE` is deprecated—use `INSERT INTO inv (sku, qty) VALUES (\'A\', 5) AS new ON DUPLICATE KEY UPDATE qty = inv.qty + new.qty;`!'],
        [['`ON DELETE RESTRICT` vs `CASCADE`', 'Blocks parent deletion vs deletes all child rows automatically', 'Never put `ON DELETE CASCADE` on financial `orders` or `ledger_entries`—use `RESTRICT` + soft deactivation!'], ['`GENERATED ALWAYS AS (...) VIRTUAL`', 'Computed on-the-fly (`0` disk bytes) and **indexable**!', 'Core mechanism for indexing JSON keys in MySQL 8!'], ['`ALGORITHM=INSTANT` (`ALTER TABLE ADD COLUMN`)', 'Adds trailing column in milliseconds via metadata change', 'Zero table copy or write lock on multi-million-row tables in MySQL 8.0.12+!']],
        "CREATE TABLE inventory_items (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  sku TEXT UNIQUE NOT NULL,\n  stock INTEGER NOT NULL,\n  unit_price REAL NOT NULL\n);\nINSERT INTO inventory_items (sku, stock, unit_price) VALUES ('MYSQL-BOOK-8', 40, 599.00);\nSELECT sku, stock, unit_price, ROUND(stock * unit_price, 2) AS stock_valuation FROM inventory_items;",
        ['**Danger of `REPLACE INTO`**: Avoid MySQL\'s non-standard `REPLACE INTO`! On duplicate key, `REPLACE INTO` physically **`DELETE`s the old row and `INSERT`s a new row**—incrementing `AUTO_INCREMENT`, firing `ON DELETE CASCADE` wiping child rows, and resetting omitted columns to defaults! Always use `INSERT ... ON DUPLICATE KEY UPDATE` instead!'],
        [['question' => 'Why is REPLACE INTO dangerous on tables referenced by ON DELETE CASCADE foreign keys?', 'answer' => 'REPLACE INTO physically DELETEs the conflicting row and INSERTs a new row, cascading deletes to child records and changing AUTO_INCREMENT IDs!', 'options' => ['REPLACE INTO physically DELETEs the conflicting row and INSERTs a new row, cascading deletes to child records and changing AUTO_INCREMENT IDs!', 'REPLACE INTO works only on MyISAM', 'It locks MySQL for 1 hour', 'It disables unique indexes']], ['question' => 'Can InnoDB create a B+Tree index on a VIRTUAL generated column (which uses 0 disk bytes in the row)?', 'answer' => 'Yes—InnoDB materializes the computed key values inside the secondary index pages!', 'options' => ['Yes—InnoDB materializes the computed key values inside the secondary index pages!', 'No, only STORED columns can be indexed', 'Only full-text indexes work', 'Virtual columns cannot use CONCAT']], ['question' => 'In MySQL 8.0.20+, what replaces the deprecated VALUES(col) function in ON DUPLICATE KEY UPDATE?', 'answer' => 'Row alias syntax: INSERT INTO t ... VALUES (...) AS new ON DUPLICATE KEY UPDATE col = new.col', 'options' => ['Row alias syntax: INSERT INTO t ... VALUES (...) AS new ON DUPLICATE KEY UPDATE col = new.col', 'INCOMING.col', 'UPSERT(col)', 'OLD.col']]],
        'Insert two more SKUs into `inventory_items` in the playground and compute total inventory value with `SUM(stock * unit_price)`.'
    ),
    my_ch('2. Joins, Subqueries, CTEs, Window Functions & JSON', 'Joins, Aggregations, Subqueries & The Infamous NOT IN (NULL) Trap', 'mysql joins inner left, count(*) vs count(col), mysql not in null returns 0 rows, not exists vs left join',
        'Master relational joins, aggregate nuances (`COUNT(*)` vs `COUNT(col)`), `ONLY_FULL_GROUP_BY` compliance, and why **`WHERE id NOT IN (SELECT parent_id FROM ...)` silently returns ZERO rows if even a single `NULL` exists in the subquery**!',
        ['**The Classic `NOT IN` + `NULL` SQL Trap!**: `x NOT IN (1, 2, NULL)` expands to `x != 1 AND x != 2 AND x != NULL`. In three-valued SQL logic, `x != NULL` is **`UNKNOWN`**, and `TRUE AND UNKNOWN` evaluates to **`UNKNOWN` (falsy in `WHERE`)**—returning **0 rows**! Always use **`NOT EXISTS (...)`** or **`LEFT JOIN ... WHERE b.id IS NULL`** for anti-joins!', '**`COUNT(*)` vs `COUNT(phone)`**: `COUNT(*)` counts all rows in the group; `COUNT(phone)` counts ONLY rows where `phone IS NOT NULL`!', '**`WHERE` vs `HAVING`**: `WHERE` filters raw rows *before* grouping (uses indexes!); `HAVING` filters aggregated groups *after* `GROUP BY`.'],
        [['`NOT EXISTS (SELECT 1 FROM ...)`', 'NULL-safe relational anti-join', 'Always prefer `NOT EXISTS` over `NOT IN (subquery)`!'], ['`COUNT(*)` vs `COUNT(col)` vs `COUNT(DISTINCT col)`', 'All rows vs non-NULL values vs unique non-NULL values', 'In InnoDB, `COUNT(*)` and `COUNT(1)` have **100% identical** execution plans!'], ['`ONLY_FULL_GROUP_BY` (Enabled in MySQL 8)', 'Forbids selecting non-aggregated columns outside `GROUP BY`', 'Prevents arbitrary random row values in grouped results (use `ANY_VALUE()` only if intentional).']],
        "SELECT c.id, c.customer_name, c.country\nFROM customers c\nWHERE NOT EXISTS (\n  SELECT 1 FROM orders o WHERE o.customer_id = c.id\n)\nORDER BY c.id ASC\nLIMIT 5;",
        ['Debunking an old myth: in MySQL InnoDB, `COUNT(1)` is **NOT** faster than `COUNT(*)`—MySQL\'s optimizer documentation explicitly confirms both compile to the exact same bytecode!'],
        [['question' => 'Why does SELECT * FROM users WHERE id NOT IN (SELECT manager_id FROM teams) return 0 rows whenever one team has manager_id = NULL?', 'answer' => 'id != NULL evaluates to UNKNOWN, making the entire NOT IN conjunction UNKNOWN (filtered out by WHERE)', 'options' => ['id != NULL evaluates to UNKNOWN, making the entire NOT IN conjunction UNKNOWN (filtered out by WHERE)', 'MySQL forbids subqueries on nullable columns', 'NOT IN sorts NULL first and stops', 'InnoDB converts NULL to 0']], ['question' => 'What is the NULL-safe replacement for WHERE id NOT IN (subquery)?', 'answer' => 'WHERE NOT EXISTS (SELECT 1 FROM ... WHERE ...)', 'options' => ['WHERE NOT EXISTS (SELECT 1 FROM ... WHERE ...)', 'WHERE id <> ALL(NULL)', 'HAVING id != NULL', 'FORCE INDEX']], ['question' => 'Is COUNT(1) faster than COUNT(*) in MySQL 8 InnoDB?', 'answer' => 'No—the MySQL optimizer treats COUNT(*) and COUNT(1) identically', 'options' => ['No—the MySQL optimizer treats COUNT(*) and COUNT(1) identically', 'Yes, COUNT(1) is 5x faster', 'COUNT(*) skips NULL rows', 'COUNT(1) counts only id=1']]],
        'Rewrite the `NOT EXISTS` query in the playground as an equivalent `LEFT JOIN orders o ON o.customer_id = c.id WHERE o.id IS NULL` and verify identical rows!'
    ),
    my_ch('2. Joins, Subqueries, CTEs, Window Functions & JSON', 'MySQL 8 CTEs (WITH / WITH RECURSIVE), Window Functions & JSON_TABLE', 'mysql 8 window functions, mysql recursive cte, mysql json ->> json_table, multi-valued index mysql',
        'MySQL 8 closed the analytical gap with enterprise RDBMSs by introducing native **CTEs (`WITH` / `WITH RECURSIVE`)**, **Window Functions** (`ROW_NUMBER`, `LAG`, `LEAD`, `NTILE`, `SUM() OVER`), **`JSON_TABLE`** (turning JSON arrays into relational SQL rows!), and **Multi-Valued JSON Array Indexes**.',
        ['**Top-N Per Category Without Self-Joins**: Before MySQL 8, finding the top 2 bestselling products per category required ugly `@row_num` session-variable hacks (now deprecated!); in MySQL 8, `ROW_NUMBER() OVER (PARTITION BY category_id ORDER BY sold DESC)` solves it cleanly!', '**`->>` Unquoting JSON Shorthand**: `doc->\'$.plan\'` returns `"\"pro\""` (with JSON quotes!), whereas `doc->>\'$.plan\'` (`JSON_UNQUOTE(JSON_EXTRACT(...))`) returns clean `' . "pro" . '`!', '**`JSON_TABLE(...)`**: Projects nested JSON arrays into typed SQL columns joinable with regular tables!'],
        [['`doc->>\'$.user.city\'`', 'Extracts & unquotes JSON path as UTF-8 text', '`WHERE doc->\'$.city\' = \'Pune\'` often fails due to quotes unless `->>` is used!'], ['`WITH RECURSIVE dates AS (...)`', 'Generates date series (filling 0-order calendar gaps in charts!)', 'Controlled by `cte_max_recursion_depth` (default `1000`).'], ['`CREATE INDEX idx_tags ON posts ((CAST(doc->\'$.tags\' AS CHAR(32) ARRAY)))`', 'MySQL 8.0.17+ Multi-Valued Index', 'Accelerates `MEMBER OF()`, `JSON_CONTAINS()`, and `JSON_OVERLAPS()`!']],
        "WITH order_totals AS (\n  SELECT customer_id, order_date, total_amount,\n         SUM(total_amount) OVER (PARTITION BY customer_id ORDER BY order_date ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_spend\n  FROM orders\n)\nSELECT * FROM order_totals ORDER BY customer_id, order_date LIMIT 8;",
        ['**Huge Chart-Building Trick**: When plotting daily orders for the last 30 days, days with `0` orders are missing from `GROUP BY DATE(created_at)`! Use a `WITH RECURSIVE calendar` CTE generating all 30 dates + `LEFT JOIN orders` so zero-sale days appear cleanly as `0`!'],
        [['question' => 'Why does WHERE profile->"$.tier" = "gold" fail to match JSON {"tier":"gold"} in MySQL unless ->> is used?', 'answer' => 'Single-arrow -> returns a quoted JSON string "\"gold\""; double-arrow ->> unquotes it to "gold"', 'options' => ['Single-arrow -> returns a quoted JSON string "\"gold\""; double-arrow ->> unquotes it to "gold"', '-> only works on integers', 'MySQL JSON paths start with @ instead of $', 'JSON columns cannot appear in WHERE']], ['question' => 'What is the default recursion limit (cte_max_recursion_depth) for WITH RECURSIVE in MySQL 8?', 'answer' => '1000 iterations', 'options' => ['1000 iterations', '10 iterations', 'Unlimited', '64 iterations']], ['question' => 'Which MySQL 8 function converts a JSON array inside a column into virtual relational rows and columns?', 'answer' => 'JSON_TABLE()', 'options' => ['JSON_TABLE()', 'JSON_EXPLODE()', 'UNNEST_JSON()', 'OPENJSON()']]],
        'Add `ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY total_amount DESC) AS biggest_order_rank` to the playground query.'
    ),
    my_ch('3. Indexing, EXPLAIN Optimization, Locking & HA', 'Composite Indexes, SARGability, Leftmost Prefix Rule & EXPLAIN Mastery', 'mysql composite index leftmost prefix, sargable queries mysql, mysql explain using filesort using temporary, invisible index',
        '90% of slow MySQL queries stem from non-**SARGable** predicates (wrapping indexed columns in functions!) or violating the **Leftmost Prefix Rule** on composite B+Tree indexes.',
        ['**Leftmost Prefix Rule**: A composite index `(a, b, c)` accelerates `(a)`, `(a, b)`, and `(a, b, c)`—it **CANNOT** seek `(b)` or `(c)` alone if `a` is missing, and if `b` uses a range (`b > 10`), `c` **cannot** be used for index filtering or sorting!', '**SARGability (Never Wrap Indexed Columns in Functions!)**: `WHERE YEAR(created_at) = 2026` forces a **Full Table Scan** because MySQL must compute `YEAR()` on every row! Rewrite as `WHERE created_at >= \'2026-01-01\' AND created_at < \'2027-01-01\'` -> instant B+Tree `range` scan!', '**Implicit Charset/Type Conversion Trap**: Querying `WHERE varchar_phone = 9876543210` (passing an integer literal to a `VARCHAR` column!) forces MySQL to cast *every* `varchar_phone` row to float—**disabling the index completely**!'],
        [['`WHERE DATE(created_at) = CURDATE()`', 'Non-SARGable (**ignores index!**)', 'Rewrite as `created_at >= CURDATE() AND created_at < CURDATE() + INTERVAL 1 DAY`!'], ['`WHERE varchar_col = 12345`', 'Implicit type cast (**ignores index!**)', 'Always quote string literals: `WHERE varchar_col = \'12345\'`!'], ['`ALTER TABLE t ALTER INDEX idx INVISIBLE;`', 'Hides index from optimizer without dropping it', 'MySQL 8 safety gem: test for 48 hours before `DROP INDEX`—re-enable in `1ms` if needed!']],
        "EXPLAIN SELECT id, order_date, total_amount\nFROM orders\nWHERE order_date >= '2023-01-01' AND order_date < '2025-01-01'\nORDER BY order_date DESC;",
        ['**Top Production MySQL Outage Saver (`INVISIBLE` Indexes)**: Before dropping a 20GB index you suspect is unused, run `ALTER TABLE orders ALTER INDEX idx_legacy INVISIBLE;`! If a monthly cron query slows down, `ALTER INDEX idx_legacy VISIBLE` restores it in **1 millisecond** instead of a 40-minute rebuild!'],
        [['question' => 'Given INDEX (tenant_id, created_at, status), which columns can utilize B+Tree key lookup in WHERE tenant_id = 5 AND created_at > "2026-01-01" AND status = "paid"?', 'answer' => 'tenant_id and created_at (the range on created_at stops B+Tree key lookup from reaching status; reorder to tenant_id, status, created_at!)', 'options' => ['tenant_id and created_at (the range on created_at stops B+Tree key lookup from reaching status; reorder to tenant_id, status, created_at!)', 'Only status', 'None of the columns', 'All three equally']], ['question' => 'Why does WHERE phone_varchar = 9876543210 perform a full table scan even when phone_varchar is indexed?', 'answer' => 'Comparing VARCHAR to an unquoted number converts every VARCHAR row to a number, invalidating the string B+Tree order', 'options' => ['Comparing VARCHAR to an unquoted number converts every VARCHAR row to a number, invalidating the string B+Tree order', 'MySQL forbids 10-digit numbers', 'Phone numbers require FULLTEXT indexes', 'InnoDB caches only strings']], ['question' => 'Which MySQL 8 feature lets you safely test whether dropping an index hurts performance—with instant 1ms rollback?', 'answer' => 'Invisible Indexes (ALTER INDEX ... INVISIBLE)', 'options' => ['Invisible Indexes (ALTER INDEX ... INVISIBLE)', 'Temporary Drop', 'Shadow Tables', 'Soft Delete Index']]],
        'Inspect the `EXPLAIN` output in the playground and compare `WHERE SUBSTR(order_date, 1, 4) = \'2024\'` vs range bounds.',
        $explainVisual
    ),
    my_ch('3. Indexing, EXPLAIN Optimization, Locking & HA', 'ACID Transactions, REPEATABLE READ, Next-Key Locks, Deadlocks, Backups & Replication', 'mysql repeatable read vs read committed, innodb gap lock next-key lock, mysql deadlock diagnosis, mysqldump single-transaction',
        'Unlike PostgreSQL and Oracle (which default to `READ COMMITTED`), **MySQL InnoDB defaults to `REPEATABLE READ`**—using **Record Locks + Gap Locks = Next-Key Locks** on locking reads/writes to prevent phantom rows!',
        ['**Critical InnoDB Locking Fact**: In InnoDB, row locks are acquired on **INDEX RECORDS**, NOT raw heap rows! If you run `UPDATE orders SET status = \'cancelled\' WHERE unindexed_note = \'x\'` (where `unindexed_note` has **NO index**!), InnoDB scans the entire Clustered Index and **locks EVERY row and gap in the entire table**!', '**Preventing & Handling Deadlocks**: Always update multiple rows/tables in deterministic ascending primary-key order (`ORDER BY id ASC`), keep transactions tiny (never call external HTTP APIs mid-transaction!), and retry `SQLSTATE 40001` (`errno 1213`) in application code.', '**Zero-Lock Production Backups**: Always pass **`--single-transaction --routines --triggers`** to `mysqldump` on InnoDB tables—without `--single-transaction`, `mysqldump` locks tables!'],
        [['`REPEATABLE READ` (InnoDB Default)', 'Consistent snapshot + Next-Key Locks on `FOR UPDATE` / `UPDATE`', 'Many high-concurrency web apps switch to `READ COMMITTED` to reduce Gap Lock deadlocks!'], ['`UPDATE` on an unindexed `WHERE` column', 'Locks **every scanned index record**!', 'Always index columns used in `UPDATE` / `DELETE` `WHERE` clauses!'], ['`mysqldump --single-transaction`', 'Takes consistent MVCC snapshot without locking InnoDB writes', 'Combine with binary logs (`--source-data=2`) for Point-in-Time Recovery (PITR).']],
        "SELECT status, COUNT(*) AS total_orders, ROUND(SUM(total_amount), 2) AS gross_volume\nFROM orders\nGROUP BY status;",
        ['**Why Switching to `READ COMMITTED` Fixes Gap-Lock Deadlocks**: Under `REPEATABLE READ`, `SELECT ... FOR UPDATE` on a non-existent ID (`WHERE email = \'new@x.com\'`) acquires a **Gap Lock**, and two concurrent inserts into the same gap deadlock when both try to insert (`Insert Intention Lock`)! `READ COMMITTED` disables most Gap Locks except foreign-key/duplicate-key checks.'],
