// Add 8 foundational & intermediate step-by-step MySQL chapters at the front so absolute beginners progress smoothly through 16 full lessons!
$mysqlFoundations = [
    my_ch('1. InnoDB Architecture, Collations & Data Types', 'SQL vs MySQL Basics: Databases, Tables, Primary Keys & CRUD Foundations', 'mysql basics for beginners, create database use, select insert update delete mysql',
        'Start from zero: **SQL** is the standard query language, while **MySQL 8** is the relational database server managing databases (`CREATE DATABASE`), tables, constraints, and `SELECT` / `INSERT` / `UPDATE` / `DELETE` statements.',
        ['**Logical SQL Execution Order (Memorize This!)**: You *write* `SELECT -> FROM -> JOIN -> WHERE -> GROUP BY -> HAVING -> ORDER BY -> LIMIT`, **but MySQL executes**: **`FROM/JOIN` -> `WHERE` -> `GROUP BY` -> `HAVING` -> `SELECT` -> `DISTINCT` -> `ORDER BY` -> `LIMIT`**!', '**Why Column Aliases Fail in `WHERE` (And Work in `ORDER BY`!)**: Because `WHERE` executes *before* `SELECT`, an alias defined in `SELECT price * 1.18 AS gst_price` does NOT exist yet during `WHERE`—but *does* exist during `ORDER BY`!'],
        [['`Execution Order`', '`FROM` -> `WHERE` -> `GROUP BY` -> `HAVING` -> `SELECT` -> `ORDER BY` -> `LIMIT`', 'Explains why `SELECT` aliases cannot be referenced in `WHERE`!'], ['`sql_safe_updates = 1`', 'Blocks `UPDATE`/`DELETE` missing a keyed `WHERE` or `LIMIT`', 'Lifesaver flag preventing accidental `DELETE FROM users;` disasters!'], ['`LIMIT 20 OFFSET 40`', 'Skips 40 rows and returns rows 41–60', 'Equivalent shorthand `LIMIT 40, 20` puts offset *first*—prefer explicit `LIMIT 20 OFFSET 40` for clarity!']],
        "SELECT id, customer_name, city, country\nFROM customers\nWHERE country IN ('Germany', 'UK', 'Sweden')\nORDER BY country ASC, customer_name ASC\nLIMIT 6;",
        ['Avoid MySQL\'s comma shorthand `LIMIT 40, 20` (where `40` is offset and `20` is count—backwards from what beginners expect!); always write `LIMIT 20 OFFSET 40`!'],
        [['question' => 'Why can\'t you reference a SELECT column alias (e.g. SELECT total * 0.1 AS tax) inside the WHERE clause?', 'answer' => 'SQL executes FROM and WHERE BEFORE evaluating the SELECT projection list', 'options' => ['SQL executes FROM and WHERE BEFORE evaluating the SELECT projection list', 'Aliases are allowed only on PostgreSQL', 'WHERE accepts only integers', 'AS is a comment keyword']], ['question' => 'In MySQL\'s legacy comma syntax LIMIT 30, 10, how many rows are returned and how many are skipped?', 'answer' => 'Skips 30 rows and returns 10 rows (prefer explicit LIMIT 10 OFFSET 30)', 'options' => ['Skips 30 rows and returns 10 rows (prefer explicit LIMIT 10 OFFSET 30)', 'Returns 30 rows and skips 10', 'Returns rows 10 through 30 (21 rows)', 'Syntax error in MySQL 8']], ['question' => 'Which MySQL session flag blocks accidental UPDATE or DELETE statements that omit a keyed WHERE clause?', 'answer' => 'sql_safe_updates = 1', 'options' => ['sql_safe_updates = 1', 'autocommit = 0', 'read_only = 2', 'strict_join = 1']]],
        'Run the `customers` query in the playground and change `LIMIT 6` to `LIMIT 3 OFFSET 2`.'
