    my_ch('1. InnoDB Architecture, Collations & Data Types', 'Filtering Deep Dive: NULL Three-Valued Logic, <=>, BETWEEN, LIKE & REGEXP', 'mysql null safe equal <=>, between inclusive dates, mysql like escape _, regexp_like mysql 8',
        'Every SQL bug hunter masters **Three-Valued Logic (`TRUE`, `FALSE`, `UNKNOWN`)**, MySQL\'s **NULL-Safe Equality Operator (`<=>`)**, `BETWEEN` timestamp boundary traps, and `LIKE` `_` underscore escaping.',
        ['**`NULL = NULL` is `UNKNOWN` (NOT `TRUE`!)**: Never write `WHERE deleted_at = NULL` (always matches 0 rows!); use `IS NULL`, `IS NOT NULL`, or MySQL\'s **NULL-safe spaceship operator `<=>`** (`NULL <=> NULL` evaluates to `1` / `TRUE`!).', '**The `BETWEEN` Midnight Timestamp Trap!**: `WHERE created_at BETWEEN \'2026-11-01\' AND \'2026-11-30\'` expands `2026-11-30` to **`2026-11-30 00:00:00`**—silently **dropping 23 hours, 59 minutes, and 59 seconds** of orders on Nov 30! Always use half-open intervals: `created_at >= \'2026-11-01\' AND created_at < \'2026-12-01\'`!', '**Underscore `_` Wildcard in `LIKE`**: In `LIKE \'admin_%\'`, `_` matches **ANY single character** (`admin1`, `adminX`, `admin_`) unless escaped (`LIKE \'admin\\\_%\'`)!'],
        [['`a <=> b` (Spaceship NULL-safe equal)', '`1` if equal OR both `NULL`; `0` if one is `NULL`', 'Cleanest way to compare two nullable columns (`WHERE old_email <=> new_email`)!'], ['`created_at >= start AND created_at < next_day`', 'Half-open date range interval', 'Avoids `BETWEEN` dropping timestamps after `00:00:00` on the end date!'], ['`LIKE \'user\\\_%\'`', 'Escapes single-char `_` wildcard', 'Forgetting `\\_` lets `userA1` match `LIKE \'user_%\'`!']],
        "SELECT id, customer_name, COALESCE(phone, 'No Phone Provided') AS contact_phone\nFROM customers\nWHERE phone IS NULL\nLIMIT 5;",
        ['**Real Accounting Bug Prevented**: Switching monthly invoice reports from `BETWEEN \'2026-03-01\' AND \'2026-03-31\'` to `>= \'2026-03-01\' AND < \'2026-04-01\'` prevents losing every invoice generated after midnight on the 31st of the month!'],
        [['question' => 'Why does WHERE order_at BETWEEN "2026-05-01" AND "2026-05-31" miss orders placed at 2:30 PM on May 31 on a DATETIME column?', 'answer' => '"2026-05-31" casts to "2026-05-31 00:00:00", excluding everything later that day; use >= "2026-05-01" AND < "2026-06-01"', 'options' => ['"2026-05-31" casts to "2026-05-31 00:00:00", excluding everything later that day; use >= "2026-05-01" AND < "2026-06-01"', 'BETWEEN excludes both endpoints', 'May has 30 days', 'DATETIME ignores hours']], ['question' => 'What does SELECT (NULL <=> NULL), (NULL = NULL) return in MySQL?', 'answer' => '1 and NULL', 'options' => ['1 and NULL', '1 and 1', '0 and 0', 'Syntax error']], ['question' => 'In SQL LIKE patterns, what does an unescaped underscore (_) match?', 'answer' => 'Any single character', 'options' => ['Any single character', 'Only literal underscores', 'Zero or more characters', 'Whitespace only']]],
        'Test `WHERE phone IS NOT NULL` vs `WHERE phone IS NULL` on `customers` in the playground.'
