        [['`MATCH(title, body) AGAINST(:q IN NATURAL LANGUAGE MODE)`', 'Relevance-ranked TF-IDF / BM25 text search', 'Automatically sorts highest-scoring rows first when used in `WHERE` without `ORDER BY`!'], ['`AGAINST(\'+mysql -legacy "clustered index"\' IN BOOLEAN MODE)`', 'Required (`+`), excluded (`-`), exact phrase (`"..."`), prefix (`opt*`)', 'Does NOT auto-sort by relevance unless you select the `MATCH(...)` score in `ORDER BY`!'], ['`innodb_ft_min_token_size = 3` (Default)', 'Words shorter than 3 chars (`AI`, `JS`, `UI`) are ignored by default!', 'Lower to `2` in `my.cnf` + run `OPTIMIZE TABLE` to index 2-letter tech terms!']],
